    private void areas(){int y=59;var list=StudioClient.a==null?new JsonArray():StudioClient.a.areas;int slots=Math.max(1,(height-151)/21);areaScroll=Math.max(0,Math.min(areaScroll,Math.max(0,list.size()-slots)));for(int i=areaScroll;i<Math.min(list.size(),areaScroll+slots);i++){var item=list.get(i).getAsJsonObject();String key=key(item);button(7,y,left-14,(selected.equals(key)?"› ":"")+font.plainSubstrByWidth(item.get("id").getAsString(),left-30),()->{select(item);});y+=21;}button(7,height-88,(left-18)/2,"↑",()->{areaScroll--;layout();});button(11+(left-18)/2,height-88,(left-18)/2,"↓",()->{areaScroll++;layout();});button(7,height-66,left-14,"New "+kind,()->{selected="";areaId="area_"+(list.size()+1);inspector=1;layout();});button(7,height-44,left-14,selected.isEmpty()?"Areas visible":"Hide / show",()->{if(!selected.isEmpty()){if(!hidden.add(selected))hidden.remove(selected);}});}
