    private void rules(int x,int w){field("ID",x,88,w,areaId,48);button(x,111,w,"Kind: "+kind,()->{if(!selected.isEmpty()){BuilderClient.error="Create a new area to change its kind.";return;}String[] kinds={"decoration","diversity","connection","shelf","table","seat"};for(int i=0;i<kinds.length;i++)if(kinds[i].equals(kind)){kind=kinds[(i+1)%kinds.length];break;}layout();});field("Category",x,143,w,category,64);if(kind.equals("connection")){button(x,166,w,"Facing: "+direction,()->{String[] dirs={"NORTH","EAST","SOUTH","WEST","UP","DOWN"};for(int i=0;i<dirs.length;i++)if(dirs[i].equals(direction)){direction=dirs[(i+1)%dirs.length];break;}layout();});field("Floor",x,191,w/2-2,floor,7);}else if(kind.equals("decoration")){button(x,166,w/2-2,fill,()->{fill=fill.equals("EXACT")?"PACKED":"EXACT";layout();});button(x+w/2+2,166,w/2-2,"Rot: "+rotate,()->{rotate=!rotate;layout();});field("Gap %",x,191,w/2-2,gap,7);button(x+w/2+2,191,w/2-2,"Stack: "+stack,()->{stack=!stack;layout();});}else if(kind.equals("diversity"))field("Weight",x,180,w,weight,12);button(x,224,w,"Apply properties",this::applyArea);}
